"""Bounded ELF32/MIPS metadata and RESET-at-zero PS2 ROMDIR inspection.

ROMDIR layout basis: ps2homebrew/ps2img at
017018224a8a77a79bf57f387bbcea3f4505c8f0, common.h and ximg.c:165-172.
This reader describes file boundaries; it does not discover raw/packed code,
apply relocations, recover functions, or prove executable coverage.
"""
from __future__ import annotations

import hashlib
import re
import struct

from evidence_common import Incomplete, Invalid


def _span(data: bytes, offset: int, size: int, label: str) -> bytes:
    if offset < 0 or size < 0 or offset > len(data) or size > len(data) - offset:
        raise Invalid(f'{label} span {offset:#x}+{size:#x} exceeds {len(data)} bytes')
    return data[offset:offset + size]


def parse_elf(data: bytes) -> dict:
    if _span(data, 0, 16, 'ELF identity')[:4] != b'\x7fELF':
        raise Invalid('ELF magic is absent')
    if data[4:7] != b'\x01\x01\x01':
        raise Incomplete('only ELF32 little-endian version 1 is supported')
    _span(data, 0, 52, 'ELF header')
    values = struct.unpack_from('<HHIIIIIHHHHHH', data, 16)
    names = ('type', 'machine', 'version', 'entry', 'program_offset',
             'section_offset', 'flags', 'header_size', 'program_stride',
             'program_count', 'section_stride', 'section_count', 'strings_section')
    result: dict = dict(zip(names, values))
    if result['machine'] != 8 or result['version'] != 1 or result['header_size'] != 52:
        raise Invalid('ELF header is not the supported 52-byte MIPS version-1 header')
    if result['program_count'] == 0xFFFF or result['strings_section'] == 0xFFFF or (
        result['section_count'] == 0 and result['section_offset'] != 0
    ):
        raise Incomplete('ELF extended section/program numbering is unsupported')
    programs = []
    if result['program_count']:
        if result['program_stride'] != 32:
            raise Invalid('ELF32 program headers must have 32-byte stride')
        _span(data, result['program_offset'], result['program_count'] * 32, 'program table')
    for i in range(result['program_count']):
        row = dict(zip(('type', 'offset', 'virtual_address', 'physical_address',
                        'file_size', 'memory_size', 'flags', 'alignment'),
                       struct.unpack_from('<8I', data, result['program_offset'] + i * 32)))
        _span(data, row['offset'], row['file_size'], f'program {i} payload')
        if row['type'] == 1 and row['memory_size'] < row['file_size']:
            raise Invalid(f'LOAD program {i} file bytes exceed memory size')
        if row['virtual_address'] + row['memory_size'] > 0x1_0000_0000:
            raise Invalid(f'program {i} virtual extent exceeds 32-bit address space')
        programs.append(row)
    sections = []
    if result['section_count']:
        if result['section_stride'] != 40:
            raise Invalid('ELF32 section headers must have 40-byte stride')
        _span(data, result['section_offset'], result['section_count'] * 40, 'section table')
    for i in range(result['section_count']):
        row = dict(zip(('name_offset', 'type', 'flags', 'address', 'offset', 'size',
                        'link', 'info', 'alignment', 'entry_size'),
                       struct.unpack_from('<10I', data, result['section_offset'] + i * 40)))
        if row['type'] not in (0, 8) and row['size']:
            _span(data, row['offset'], row['size'], f'section {i} payload')
        if row['address'] + row['size'] > 0x1_0000_0000:
            raise Invalid(f'section {i} extent exceeds 32-bit address space')
        sections.append(row)
    if result['strings_section']:
        if result['strings_section'] >= len(sections):
            raise Invalid('section-name string table index is out of range')
        table = sections[result['strings_section']]
        if table['type'] != 3:
            raise Invalid('section-name table is not STRTAB')
        strings = _span(data, table['offset'], table['size'], 'section names')
        for row in sections:
            at = row['name_offset']
            end = strings.find(b'\0', at)
            if at >= len(strings) or end < 0:
                raise Invalid('section name exceeds string table')
            row['name'] = strings[at:end].decode('ascii', errors='backslashreplace')
    result.update(programs=programs, sections=sections,
                  bytes=len(data), sha256=hashlib.sha256(data).hexdigest())
    return result


def parse_romdir(data: bytes) -> dict:
    """Inspect measured RESET-size-zero profile; do not guess generic BIOS starts."""
    _span(data, 0, 48, 'ROMDIR prefix')
    prefix = [struct.unpack_from('<10sHI', data, at) for at in (0, 16, 32)]
    if [row[0].split(b'\0', 1)[0] for row in prefix] != [b'RESET', b'ROMDIR', b'EXTINFO']:
        raise Incomplete('only RESET/ROMDIR/EXTINFO-at-zero profile is supported')
    if prefix[0][2] != 0:
        raise Incomplete('nonempty RESET bootstrap is outside the supported profile')
    directory_size = prefix[1][2]
    if directory_size < 64 or directory_size % 16:
        raise Invalid('ROMDIR size must include entries and a 16-byte terminator')
    directory = _span(data, 0, directory_size, 'ROMDIR table')
    entries = []
    for at in range(0, directory_size - 16, 16):
        raw_name, extended_size, size = struct.unpack_from('<10sHI', directory, at)
        if b'\0' not in raw_name:
            raise Invalid('ROMDIR name is not terminated within ten bytes')
        name = raw_name.split(b'\0', 1)[0]
        if not re.fullmatch(rb'[A-Z0-9_]{1,9}', name):
            raise Invalid('ROMDIR name is empty or outside the safe measured character set')
        if any(raw_name[len(name) + 1:]):
            raise Invalid('ROMDIR name has nonzero trailing bytes')
        entries.append({'name': name.decode('ascii'), 'extended_info_bytes': extended_size,
                        'bytes': size, 'directory_offset': at})
    if any(directory[-16:]):
        raise Invalid('ROMDIR terminator is not sixteen zero bytes')
    if len({row['name'] for row in entries}) != len(entries):
        raise Invalid('ROMDIR contains duplicate names')
    if sum(row['extended_info_bytes'] for row in entries) != prefix[2][2]:
        raise Invalid('ROMDIR extended-info lengths do not match EXTINFO size')
    _span(data, directory_size, prefix[2][2], 'EXTINFO payload')
    cursor = (directory_size + prefix[2][2] + 15) & ~15
    _span(data, directory_size + prefix[2][2], cursor - directory_size - prefix[2][2], 'EXTINFO padding')
    modules = []
    logical_end = cursor
    for row in entries[3:]:
        payload = _span(data, cursor, row['bytes'], row['name'] + ' module')
        modules.append({**row, 'offset': cursor, 'sha256': hashlib.sha256(payload).hexdigest(),
                        'elf': parse_elf(payload)})
        logical_end = cursor + row['bytes']
        cursor = (logical_end + 15) & ~15
    if len(data) < logical_end or len(data) > cursor:
        raise Invalid('ROMDIR payload end differs from file end or final alignment')
    return {'entries': entries, 'modules': modules, 'logical_end': logical_end,
            'padding_bytes': len(data) - logical_end,
            'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}

#!/usr/bin/env python3
"""Inventory bounded ELF/ROMDIR headers in a local extracted PS2 disc tree."""
import argparse
import hashlib
import mmap
from pathlib import Path

from evidence_common import Incomplete, write_result
from ps2_executables import parse_elf, parse_romdir


def inventory(root: Path) -> dict:
    if not root.is_dir():
        raise Incomplete(f'extracted root is missing: {root}')
    files, executables, unknown = [], [], []
    for path in sorted(p for p in root.rglob('*') if p.is_file()):
        digest = hashlib.sha256()
        size = path.stat().st_size
        offsets = []
        with path.open('rb') as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                digest.update(chunk)
            if size:
                with mmap.mmap(stream.fileno(), 0, access=mmap.ACCESS_READ) as mapped:
                    start = 0
                    while True:
                        at = mapped.find(b'\x7fELF', start)
                        if at < 0:
                            break
                        offsets.append(at)
                        start = at + 4
        relative = path.relative_to(root).as_posix()
        file_info = {'path': relative, 'bytes': size, 'sha256': digest.hexdigest(),
                     'elf_magic_offsets': offsets}
        files.append(file_info)
        if not offsets:
            continue
        with path.open('rb') as stream:
            prefix = stream.read(16)
        if prefix.startswith(b'RESET\0'):
            container = parse_romdir(path.read_bytes())
            known = [row['offset'] for row in container['modules']]
            executables.extend({'container': relative, **row} for row in container['modules'])
        elif prefix.startswith(b'\x7fELF'):
            executables.append({'container': relative, 'name': path.name, 'offset': 0,
                                'bytes': size, 'sha256': digest.hexdigest(),
                                'elf': parse_elf(path.read_bytes())})
            known = [0]
        else:
            known = []
        unknown.extend({'path': relative, 'offset': at}
                       for at in offsets if at not in known)
    details = {'file_count': len(files), 'files': files, 'executable_count': len(executables),
               'executables': executables, 'unclassified_elf_magic': unknown,
               'claim_limits': ['ELF/ROMDIR header and payload bounds only.',
                                'Raw overlays, packed code and VU programs are not discovered by ELF magic.',
                                'No relocation, function discovery or behavioral equivalence is established.']}
    if unknown:
        raise Incomplete('ELF magic candidates remain unclassified', details)
    if not executables:
        raise Incomplete('no supported ELF executables were found', details)
    return details


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('root', type=Path)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    return write_result(args.output, 'executables', lambda: inventory(args.root), [])


if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Verify exact IRX slices from the pinned ELF inventory and ROMDIR boundaries."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from evidence_common import Incomplete, Invalid, write_result
from ps2_executables import parse_romdir
from ps2_irx import parse_irx


def _json(path: Path, label: str) -> dict:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise Incomplete(f"required {label} is missing: {path}") from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise Invalid(f"cannot read {label}: {type(exc).__name__}: {exc}") from exc
    if not isinstance(value, dict):
        raise Invalid(f"{label} must be a JSON object")
    return value


def _local_path(root: Path, listed: str) -> Path:
    path = Path(listed)
    if path.is_absolute():
        try:
            return path.resolve().relative_to(root.resolve())
        except ValueError as exc:
            raise Invalid(f"inventory source path escapes extracted root: {listed}") from exc
    parts = path.parts
    if "extracted" in parts:
        parts = parts[parts.index("extracted") + 1 :]
    result = (root / Path(*parts)).resolve()
    if not result.is_relative_to(root.resolve()):
        raise Invalid(f"inventory source path escapes extracted root: {listed}")
    return result


def verify_corpus(root: Path, inventory_path: Path, boundaries_path: Path) -> dict:
    """Check every IRX candidate against its exact local source bytes and parse it."""
    if not root.is_dir():
        raise Incomplete(f"extracted root is missing: {root}")
    inventory = _json(inventory_path, "ELF inventory")
    boundaries = _json(boundaries_path, "ROMDIR boundary inventory")
    if not isinstance(inventory.get("elf_magic_candidates"), list):
        raise Invalid("ELF inventory is missing elf_magic_candidates")
    if not isinstance(boundaries.get("standalone"), list) or not isinstance(boundaries.get("modules"), list):
        raise Invalid("boundary inventory is missing standalone or embedded module lists")
    expected_root = inventory.get("root")
    if isinstance(expected_root, str) and Path(expected_root).resolve() != root.resolve():
        raise Invalid("requested extracted root differs from the root recorded in ELF inventory")

    candidates = [row for row in inventory["elf_magic_candidates"]
                  if isinstance(row, dict) and row.get("type") == 0xFF80]
    if len(candidates) != 24:
        raise Invalid(f"pinned inventory must contain 24 ET 0xff80 candidates, got {len(candidates)}")
    candidate_keys = set()
    candidates_by_source: dict[str, list[dict]] = {}
    for row in candidates:
        file_name = row.get("file")
        offset = row.get("offset")
        if not isinstance(file_name, str) or type(offset) is not int or offset < 0:
            raise Invalid("IRX candidate has an invalid source path or offset")
        if row.get("machine") != 8 or not row.get("valid_header"):
            raise Invalid(f"IRX candidate header is not valid MIPS: {file_name}@{offset:#x}")
        key = (file_name, offset)
        if key in candidate_keys:
            raise Invalid(f"duplicate IRX candidate in inventory: {file_name}@{offset:#x}")
        candidate_keys.add(key)
        candidates_by_source.setdefault(file_name, []).append(row)

    standalone_paths = {row.get("path") for row in boundaries["standalone"] if isinstance(row, dict)}
    standalone_candidates = [row for row in candidates if row.get("offset") == 0]
    if len(standalone_candidates) != 9:
        raise Invalid(f"pinned inventory must contain nine standalone IRX candidates, got {len(standalone_candidates)}")
    for row in standalone_candidates:
        if row["file"] not in standalone_paths:
            raise Invalid(f"standalone IRX is absent from boundary inventory: {row['file']}")
        boundary_row = next(item for item in boundaries["standalone"]
                            if isinstance(item, dict) and item.get("path") == row["file"])
        elf = boundary_row.get("elf")
        if (not isinstance(elf, dict) or elf.get("type") != 0xFF80
                or elf.get("machine") != 8 or elf.get("bytes") != row.get("file_bytes")
                or elf.get("sha256") != row.get("sha256")):
            raise Invalid(f"standalone IRX identity differs from boundary inventory: {row['file']}")

    embedded = boundaries["modules"]
    if len(embedded) != 15:
        raise Invalid(f"pinned ROMDIR boundary inventory must contain 15 modules, got {len(embedded)}")
    image_path = (root / "IRX" / "IOPRP255.IMG").resolve()
    if not image_path.is_file():
        raise Incomplete(f"embedded IRX image is missing: {image_path}")
    image_data = image_path.read_bytes()
    boundary_digest = hashlib.sha256(image_data).hexdigest()
    if (boundaries.get("bytes") != len(image_data)
            or boundaries.get("sha256") != boundary_digest):
        raise Invalid("IOPRP255.IMG identity differs from pinned ROMDIR boundary inventory")
    romdir = parse_romdir(image_data)
    actual_romdir = [(row["name"], row["offset"], row["bytes"], row["sha256"])
                     for row in romdir["modules"]]
    expected_romdir = [(row.get("name"), row.get("offset"), row.get("bytes"), row.get("sha256"))
                       for row in embedded]
    if actual_romdir != expected_romdir:
        raise Invalid("ROMDIR-derived module bounds differ from pinned boundary inventory")

    image_candidate_file = next((key[0] for key in candidate_keys if key[0].endswith("IOPRP255.IMG")), None)
    if not image_candidate_file:
        raise Invalid("ELF inventory has no IOPRP255.IMG IRX candidates")
    embedded_candidates = candidates_by_source.get(image_candidate_file, [])
    if len(embedded_candidates) != 15:
        raise Invalid(f"ELF inventory must list 15 embedded IRX candidates, got {len(embedded_candidates)}")
    expected_pairs = {(row["offset"], row["bytes"]) for row in embedded}
    actual_pairs = set()
    for row in embedded_candidates:
        match = next((item for item in embedded if item["offset"] == row["offset"]), None)
        if match is None:
            raise Invalid(f"embedded ELF candidate is absent from ROMDIR boundaries at {row['offset']:#x}")
        actual_pairs.add((row["offset"], match["bytes"]))
        if row.get("machine") != 8 or not row.get("valid_header"):
            raise Invalid(f"embedded IRX candidate header is not valid MIPS: {row['offset']:#x}")
    if actual_pairs != expected_pairs:
        raise Invalid("embedded ELF candidates do not cover exact ROMDIR module bounds")

    modules = []
    origin_paths: set[Path] = {image_path}
    for candidate in sorted(candidates, key=lambda row: (row["file"], row["offset"])):
        source = _local_path(root, candidate["file"])
        source = source if source.is_absolute() else (root / source).resolve()
        if not source.is_file():
            raise Incomplete(f"IRX candidate source is missing: {source}")
        source_data = source.read_bytes()
        if hashlib.sha256(source_data).hexdigest() != candidate.get("sha256"):
            raise Invalid(f"IRX candidate source file identity changed: {source}")
        if candidate.get("file_bytes") != len(source_data):
            raise Invalid(f"IRX candidate source byte count changed: {source}")
        origin_paths.add(source)
        offset = candidate["offset"]
        if source == image_path:
            boundary = next(row for row in embedded if row["offset"] == offset)
            size = boundary["bytes"]
            payload = source_data[offset : offset + size]
            name = boundary["name"]
            expected_digest = boundary["sha256"]
        else:
            if offset != 0:
                raise Invalid(f"standalone IRX candidate has nonzero offset: {source}@{offset:#x}")
            size = len(source_data)
            payload = source_data
            name = source.name
            expected_digest = candidate["sha256"]
        actual_digest = hashlib.sha256(payload).hexdigest()
        if len(payload) != size or actual_digest != expected_digest:
            raise Invalid(f"IRX slice bounds/hash differ from pinned metadata: {source}@{offset:#x}")
        parsed = parse_irx(payload, source=str(source.relative_to(root.resolve())) + f"@0x{offset:x}")
        if parsed["sha256"] != actual_digest:
            raise Invalid(f"parsed IRX identity differs from exact source slice: {name}")
        modules.append({"name": name, "source": str(source.relative_to(root.resolve())),
                        "offset": offset, "bytes": size, "sha256": actual_digest,
                        "elf_type": parsed["elf_type"], "machine": parsed["machine"],
                        "iopmod_name": parsed["module"]["name"],
                        "iopmod_entry": parsed["module"]["entry_address"],
                        "counts": parsed["counts"]})

    if len(modules) != 24:
        raise Invalid(f"parsed IRX module count differs from pinned candidate count: {len(modules)}")
    totals = {key: sum(module["counts"][key] for module in modules)
              for key in ("import_libraries", "import_stubs", "export_libraries", "export_links")}
    return {
        "module_count": len(modules),
        "standalone_count": len(standalone_candidates),
        "romdir_module_count": len(embedded),
        "modules": modules,
        "totals": totals,
        "claim_limits": [
            "This inventory covers only the 24 ELF32LE MIPS ET 0xff80 IRX candidates in the pinned inventory.",
            "IRX import indices are numeric; function names need a matching IOP library/version/index catalog.",
            "Export offsets are recorded but not proven to be callable function entries.",
            "The parser does not apply Sony ET 0xff80 relocations or verify runtime GP values.",
            "IRX coverage does not establish whole-game code coverage or recovered source.",
        ],
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path, help="exact extracted game root recorded by the inventory")
    parser.add_argument("--inventory", type=Path, required=True)
    parser.add_argument("--boundaries", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    inputs = [args.inventory, args.boundaries]
    # write_result records the full hashes of every source container used by the check.
    if args.root.is_dir():
        inputs.extend(sorted({p for p in args.root.rglob("*") if p.is_file()
                              and (p.name == "IOPRP255.IMG" or p.suffix.upper() == ".IRX")}))
    return write_result(args.output, "iop-irx", lambda: verify_corpus(args.root, args.inventory, args.boundaries), inputs)


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Verify a Ghidra pseudocode export against a static function inventory.

This checks export provenance, address coverage, artifact integrity, and
decompiler output comments. It does not establish whole-game code discovery,
original-source recovery, or behavioral equivalence.
"""

import argparse
from collections import Counter, defaultdict
import hashlib
import json
from pathlib import Path
import re

from evidence_common import Incomplete, Invalid, identity, write_result

CHECK = "decompilation"
WARNING_TOKEN = re.compile(r"\bWARNING\b", re.IGNORECASE)
MAX_MISSING_SAMPLE = 20
WARNING_CATEGORIES = (
    ("subroutine does not return", re.compile(r"subroutine does not return", re.I)),
    ("overlapping global symbols", re.compile(r"globals starting with .+ overlap smaller symbols", re.I)),
    ("unreachable block", re.compile(r"removing unreachable block", re.I)),
    ("infinite-loop do-nothing block", re.compile(r"do nothing block with infinite loop", re.I)),
    ("type propagation did not settle", re.compile(r"type propagation algorithm not settling", re.I)),
    ("decompiler restart limit", re.compile(r"exceeded maximum restarts", re.I)),
    ("decompiler restarted for space", re.compile(r"restarted to delay deadcode elimination", re.I)),
    ("case-label calculation failed", re.compile(r"calculation of case label failed", re.I)),
    ("heritage after dead-code removal", re.compile(r"heritage after dead removal", re.I)),
    ("possible position-independent-code construction", re.compile(r"possible pic construction", re.I)),
    ("overlapping instruction decode", re.compile(r"instruction .+ overlaps instruction", re.I)),
    ("jump-table recovery failed", re.compile(r"could not recover jumptable", re.I)),
    ("indirect jump treated as a call", re.compile(r"treating indirect jump as call", re.I)),
)


def _read_json(path: Path, label: str) -> dict:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise Invalid(f"cannot read {label}: {type(exc).__name__}: {exc}") from exc
    if not isinstance(value, dict):
        raise Invalid(f"{label} must be a JSON object")
    return value


def _c_comments(source: str):
    """Yield C comments while skipping string and character literal contents."""
    i, size = 0, len(source)
    while i < size:
        if source.startswith("//", i):
            end = source.find("\n", i + 2)
            if end < 0:
                end = size
            yield source[i:end]
            i = end
        elif source.startswith("/*", i):
            end = source.find("*/", i + 2)
            if end < 0:
                yield source[i:]
                return
            end += 2
            yield source[i:end]
            i = end
        elif source[i] in {"'", '"'}:
            quote = source[i]
            i += 1
            while i < size:
                if source[i] == "\\":
                    i += 2
                elif source[i] == quote:
                    i += 1
                    break
                else:
                    i += 1
        else:
            i += 1


def _warning_category(comment: str) -> str:
    for label, pattern in WARNING_CATEGORIES:
        if pattern.search(comment):
            return label
    return "other warning"
def _entry(value, label):
    if not isinstance(value, str) or not re.fullmatch(r"[0-9a-fA-F]{8}", value):
        raise Invalid(f"{label} is not an eight-digit function address")
    return value.lower()


def _count(value, label):
    if type(value) is not int or value < 0:
        raise Invalid(f"{label} must be a non-negative integer")
    return value


def _artifact_path(manifest_path: Path, relative: str, entry: str) -> Path:
    expected = f"functions/{entry}.c"
    if relative != expected:
        raise Invalid(f"unexpected pseudocode path for {entry}: {relative!r}")
    root = manifest_path.parent.resolve()
    artifact = (manifest_path.parent / relative).resolve()
    if not artifact.is_relative_to(root):
        raise Invalid(f"pseudocode path escapes export directory: {relative!r}")
    return artifact


def verify(manifest_path: Path, static_path: Path, executable_path: Path) -> dict:
    """Verify one export. Raises Invalid for contradictions and Incomplete for gaps."""
    manifest = _read_json(manifest_path, "decompilation manifest")
    static = _read_json(static_path, "static function inventory")
    if type(manifest.get("schema_version")) is not int or type(static.get("schema_version")) is not int or manifest["schema_version"] != 1 or static["schema_version"] != 1:
        raise Invalid("unsupported decompilation or static-export schema version")

    actual_executable = identity(executable_path)
    for label, value in (
        ("manifest program", manifest.get("program")),
        ("manifest language", manifest.get("language")),
        ("static program", static.get("program")),
        ("static language", static.get("language")),
    ):
        if not isinstance(value, str) or not value:
            raise Invalid(f"{label} must be non-empty text")
    if not (
        isinstance(manifest.get("executable_sha256"), str)
        and manifest["executable_sha256"] == static.get("executable_sha256")
        and manifest["executable_sha256"] == actual_executable["sha256"]
    ):
        raise Invalid("decompilation manifest, static inventory, and executable identities differ")
    if manifest.get("program") != static.get("program") or manifest.get("language") != static.get("language"):
        raise Invalid("decompilation manifest and static inventory program identity differ")

    static_rows = static.get("functions")
    if not isinstance(static_rows, list):
        raise Invalid("static inventory functions must be an array")
    expected = [_entry(row.get("entry"), "static function entry") for row in static_rows if isinstance(row, dict)]
    if len(expected) != len(static_rows):
        raise Invalid("static inventory contains a malformed function row")
    if len(set(expected)) != len(expected):
        raise Invalid("static inventory contains duplicate function addresses")
    if _count(static.get("inventory_count"), "static inventory_count") != len(expected) or not expected:
        raise Invalid("static inventory claimed count does not match its function rows")

    if _count(manifest.get("inventory_count"), "manifest inventory_count") != len(expected):
        raise Invalid("decompilation manifest claimed inventory_count differs from static inventory")
    scope = manifest.get("scope")
    if not isinstance(scope, str) or scope not in {"all saved functions", "selected entry addresses"}:
        raise Invalid("unknown decompilation scope")
    rows = manifest.get("functions")
    if not isinstance(rows, list):
        raise Invalid("decompilation functions must be an array")
    if _count(manifest.get("processed"), "manifest processed") != len(rows):
        raise Invalid("manifest processed count differs from function rows")
    if len(rows) > len(expected):
        raise Invalid("decompilation function rows exceed static inventory")

    entries = []
    status_counts = {"generated": 0, "failed": 0}
    generated_entries = set()
    failures = []
    warnings = []
    warning_category_counts = Counter()
    warning_category_entries = defaultdict(set)
    for row in rows:
        if not isinstance(row, dict):
            raise Invalid("decompilation manifest contains a malformed function row")
        entry = _entry(row.get("entry"), "decompilation entry")
        entries.append(entry)
        if entry not in set(expected):
            raise Invalid(f"decompilation function address is absent from static inventory: {entry}")
        status = row.get("status")
        if not isinstance(status, str) or status not in status_counts:
            raise Invalid(f"unknown decompilation row status for {entry}: {status!r}")
        status_counts[status] += 1
        message = row.get("message", "")
        if not isinstance(message, str):
            raise Invalid(f"decompiler message for {entry} must be text")
        if status == "failed":
            failures.append({"entry": entry, "message": message})
            continue

        relative = row.get("path")
        if not isinstance(relative, str):
            raise Invalid(f"generated function {entry} has no artifact path")
        artifact = _artifact_path(manifest_path, relative, entry)
        try:
            data = artifact.read_bytes()
        except OSError as exc:
            raise Invalid(f"generated pseudocode is missing or unreadable for {entry}: {exc}") from exc
        digest = hashlib.sha256(data).hexdigest()
        if row.get("bytes") != len(data) or row.get("sha256") != digest:
            raise Invalid(f"generated pseudocode bytes or SHA-256 differ for {entry}")
        try:
            source = data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise Invalid(f"generated pseudocode is not UTF-8 for {entry}") from exc
        generated_entries.add(entry)
        for comment in _c_comments(source):
            if WARNING_TOKEN.search(comment):
                category = _warning_category(comment)
                warning_category_counts[category] += 1
                warning_category_entries[category].add(entry)
                warnings.append({"entry": entry, "text": comment})

    if len(set(entries)) != len(entries):
        raise Invalid("decompilation manifest contains duplicate function addresses")
    if _count(manifest.get("generated"), "manifest generated") != status_counts["generated"]:
        raise Invalid("manifest generated count differs from generated function rows")
    if _count(manifest.get("failed"), "manifest failed") != status_counts["failed"]:
        raise Invalid("manifest failed count differs from failed function rows")
    if len(generated_entries) != status_counts["generated"]:
        raise Invalid("generated address coverage does not match generated count")

    function_root = manifest_path.parent / "functions"
    recorded_paths = {
        _artifact_path(manifest_path, row["path"], _entry(row["entry"], "decompilation entry"))
        for row in rows
        if isinstance(row, dict) and row.get("status") == "generated" and isinstance(row.get("path"), str)
    }
    if function_root.exists():
        unlisted = [
            p for p in function_root.rglob("*.c")
            if p.resolve() not in recorded_paths
        ]
        if unlisted:
            raise Invalid(f"unlisted pseudocode artifacts found: {len(unlisted)}")

    actual_entries = set(entries)
    expected_entries = set(expected)
    missing = sorted(expected_entries - actual_entries) if scope == "all saved functions" else []
    if "missing_selected_entries" not in manifest:
        raise Invalid("manifest is missing missing_selected_entries")
    missing_selected = manifest["missing_selected_entries"]
    if not isinstance(missing_selected, list):
        raise Invalid("missing_selected_entries must be an array")
    normalized_selected_missing = [_entry(value, "missing selected entry") for value in missing_selected]
    if len(set(normalized_selected_missing)) != len(normalized_selected_missing):
        raise Invalid("missing_selected_entries contains duplicate addresses")
    if set(normalized_selected_missing) & actual_entries:
        raise Invalid("missing selected entries overlap processed function rows")

    terminal_reason = manifest.get("terminal_reason")
    manifest_status = manifest.get("status")
    if not isinstance(terminal_reason, str) or not terminal_reason:
        raise Invalid("manifest terminal_reason must be non-empty text")
    if manifest_status not in {"generated", "incomplete"}:
        raise Invalid("unknown manifest terminal status")
    internally_complete = (
        status_counts["failed"] == 0
        and not normalized_selected_missing
        and terminal_reason == "function iteration finished"
        and (scope != "all saved functions" or set(entries) == expected_entries)
    )
    expected_manifest_status = "generated" if internally_complete else "incomplete"
    if manifest_status != expected_manifest_status:
        raise Invalid("manifest status disagrees with failures, missing entries, or terminal reason")

    details = {
        "program": manifest["program"],
        "language": manifest["language"],
        "executable_sha256": actual_executable["sha256"],
        "static_inventory_sha256": identity(static_path)["sha256"],
        "manifest_sha256": identity(manifest_path)["sha256"],
        "inventory_count": len(expected),
        "processed_count": len(rows),
        "generated_count": status_counts["generated"],
        "failed_count": status_counts["failed"],
        "decompile_failures": failures,
        "failed_functions": failures,
        "missing_inventory_entry_count": len(missing),
        "missing_inventory_entry_sample": missing[:MAX_MISSING_SAMPLE],
        "missing_selected_entries": normalized_selected_missing,
        "warning_comment_count": len(warnings),
        "warning_comments": warnings,
        "warning_categories": [
            {
                "category": category,
                "count": count,
                "affected_function_count": len(warning_category_entries[category]),
                "entries": sorted(warning_category_entries[category]),
            }
            for category, count in sorted(
                warning_category_counts.items(), key=lambda item: (-item[1], item[0])
            )
        ],
        "scope": scope,
        "terminal_reason": terminal_reason,
        "claim_limit": "Function inventory coverage is limited to the supplied static export; this check does not prove whole-game code discovery, original-source recovery, or behavioral equivalence.",
    }
    gaps = []
    if status_counts["failed"]:
        gaps.append(f"{status_counts['failed']} decompilation failures")
    if normalized_selected_missing:
        gaps.append(f"{len(normalized_selected_missing)} requested functions missing")
    if missing:
        gaps.append(f"{len(missing)} static inventory functions not present in export")
    if scope != "all saved functions":
        gaps.append("export scope is selected functions, not the full static inventory")
    if manifest_status != "generated":
        gaps.append("export manifest is incomplete")
    if gaps:
        details["status"] = "incomplete"
        details["failures"] = []
        raise Incomplete("; ".join(gaps), details)
    details["status"] = "pass"
    details["failures"] = []
    return details


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--static-export", type=Path, default=Path(".scratch/evidence/static-export.json"))
    parser.add_argument("--executable", type=Path, default=Path("games/ford-racing-2/extracted/SLES_517.05"))
    parser.add_argument("--output", type=Path, default=Path(".scratch/evidence/decompilation"))
    args = parser.parse_args()
    return write_result(
        args.output,
        CHECK,
        lambda: verify(args.manifest, args.static_export, args.executable),
        [args.manifest, args.static_export, args.executable],
    )


if __name__ == "__main__":
    raise SystemExit(main())

// @category Analysis
import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.*;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Read-only batch pseudocode export; success records are not equivalence proofs. */
public class ExportDecompilation extends GhidraScript {
    private String hash(byte[] bytes) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
    }

    public void run() throws Exception {
        String[] args = getScriptArgs();
        if (args.length < 1 || args.length > 3)
            throw new IllegalArgumentException("output directory [timeout seconds] [comma-separated entry addresses]");
        int timeout = args.length > 1 ? Integer.parseInt(args[1]) : 30;
        if (timeout < 1 || timeout > 600) throw new IllegalArgumentException("timeout outside 1..600");
        Set<String> selected = new HashSet<>();
        if (args.length > 2) {
            for (String token : args[2].split(",", -1)) {
                String address = token.trim().toLowerCase(Locale.ROOT);
                if (!address.matches("[0-9a-f]{8}"))
                    throw new IllegalArgumentException("Selected addresses must be eight hexadecimal digits");
                selected.add(address);
            }
        }
        Path out = Paths.get(args[0]).toAbsolutePath();
        Files.createDirectories(out.getParent());
        Files.createDirectory(out); // never overwrite a previous run
        Path sources = Files.createDirectory(out.resolve("functions"));
        JsonObject manifest = new JsonObject();
        manifest.addProperty("schema_version", 1);
        manifest.addProperty("program", currentProgram.getName());
        manifest.addProperty("language", currentProgram.getLanguageID().toString());
        manifest.addProperty("executable_sha256", currentProgram.getExecutableSHA256());
        manifest.addProperty("ghidra_version", getGhidraVersion());
        manifest.addProperty("inventory_count", currentProgram.getFunctionManager().getFunctionCount());
        manifest.addProperty("timeout_seconds", timeout);
        manifest.addProperty("scope", selected.isEmpty() ? "all saved functions" : "selected entry addresses");
        manifest.addProperty("status", "incomplete");
        manifest.addProperty("terminal_reason", "export did not finish");
        manifest.addProperty("claim_limits", "Generated pseudocode only. Successful decompilation does not prove recovered original source, correct types, complete code discovery, recompilability, or behavioral equivalence.");
        JsonArray rows = new JsonArray();
        manifest.add("functions", rows);
        DecompInterface decompiler = new DecompInterface();
        int successes = 0, failures = 0;
        Set<String> visited = new HashSet<>();
        boolean normalCompletion = false;
        try {
            decompiler.setSimplificationStyle("decompile");
            decompiler.toggleCCode(true);
            decompiler.toggleSyntaxTree(true);
            if (!decompiler.openProgram(currentProgram))
                throw new IllegalStateException("Cannot open decompiler: " + decompiler.getLastMessage());
            for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
                monitor.checkCancelled();
                String entry = f.getEntryPoint().toString();
                if (!selected.isEmpty() && !selected.contains(entry)) continue;
                visited.add(entry);
                JsonObject row = new JsonObject();
                row.addProperty("entry", entry);
                row.addProperty("name", f.getName());
                row.addProperty("body_bytes", f.getBody().getNumAddresses());
                row.addProperty("external", f.isExternal());
                row.addProperty("thunk", f.isThunk());
                rows.add(row);
                long started = System.nanoTime();
                try {
                    DecompileResults result = decompiler.decompileFunction(f, timeout, monitor);
                    row.addProperty("completed", result.decompileCompleted());
                    row.addProperty("message", result.getErrorMessage());
                    DecompiledFunction df = result.getDecompiledFunction();
                    if (!result.decompileCompleted() || df == null || df.getC() == null || df.getC().isBlank()) {
                        row.addProperty("status", "failed");
                        failures++;
                    } else {
                        String filename = entry + ".c";
                        byte[] bytes = df.getC().getBytes(StandardCharsets.UTF_8);
                        Path temporary = Files.createTempFile(sources, entry + "-", ".partial");
                        try {
                            Files.write(temporary, bytes, StandardOpenOption.TRUNCATE_EXISTING);
                            Files.move(temporary, sources.resolve(filename), StandardCopyOption.ATOMIC_MOVE);
                        } finally {
                            Files.deleteIfExists(temporary);
                        }
                        row.addProperty("status", "generated");
                        row.addProperty("path", "functions/" + filename);
                        row.addProperty("sha256", hash(bytes));
                        row.addProperty("bytes", bytes.length);
                        successes++;
                    }
                } catch (Exception e) {
                    row.addProperty("status", "failed");
                    row.addProperty("message", e.getClass().getSimpleName() + ": " + e.getMessage());
                    failures++;
                }
                row.addProperty("milliseconds", (System.nanoTime() - started) / 1000000);
                if (rows.size() % 100 == 0) println("DECOMP_PROGRESS processed=" + rows.size() + " generated=" + successes + " failed=" + failures);
            }
            normalCompletion = true;
            manifest.addProperty("terminal_reason", "function iteration finished");
        } catch (Exception e) {
            manifest.addProperty("terminal_reason", e.getClass().getSimpleName() + ": " + e.getMessage());
            throw e;
        } finally {
            try {
                decompiler.dispose();
            } catch (Exception cleanup) {
                normalCompletion = false;
                manifest.addProperty("cleanup_warning", cleanup.getClass().getSimpleName() + ": " + cleanup.getMessage());
            }
            Set<String> missing = new TreeSet<>(selected);
            missing.removeAll(visited);
            JsonArray absent = new JsonArray();
            for (String entry : missing) absent.add(entry);
            manifest.add("missing_selected_entries", absent);
            manifest.addProperty("status", normalCompletion && failures == 0 && missing.isEmpty() ? "generated" : "incomplete");
            manifest.addProperty("processed", rows.size());
            manifest.addProperty("generated", successes);
            manifest.addProperty("failed", failures);
            Files.writeString(out.resolve("manifest.json"), new GsonBuilder().setPrettyPrinting().create().toJson(manifest) + "\n", StandardCharsets.UTF_8, StandardOpenOption.CREATE_NEW);
        }
        println("DECOMP_EXPORT processed=" + rows.size() + " generated=" + successes + " failed=" + failures + " output=" + out);
    }
}

